"""Client helpers for the internal pricing service."""

import json
import os
import urllib.error
import urllib.request

BASE = os.environ.get("PRICE_SERVICE_URL", "http://prices.internal/api/v2/price").rstrip("/")


def get_price(sku: str) -> float:
    """Return the current service price for *sku*."""
    request = urllib.request.Request(f"{BASE}/{sku}")
    pricing_key = os.environ.get("PRICING_KEY")
    if pricing_key:
        request.add_header("X-Pricing-Key", pricing_key)

    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list[str]) -> float:
    """Return the sum of the current prices for all supplied SKUs."""
    return sum(map(get_price, skus), 0.0)
